package com.ecommerce.product; import com.ecommerce.seller.*; import com.ecommerce.inventory.*; import com.ecommerce.user.*; import com.ecommerce.common.ApiException; import jakarta.validation.constraints.*; import org.springframework.data.domain.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/api/v1") public class ProductController { record ProductRequest(@NotBlank String name,String description,@NotNull @DecimalMin("0.00") BigDecimal price,@NotNull UUID categoryId){} record StockRequest(@Min(0) int quantity){} private final ProductRepository products; private final CategoryRepository cats; private final SellerRepository sellers; private final UserRepository users; private final InventoryRepository inventory; public ProductController(ProductRepository p,CategoryRepository c,SellerRepository s,UserRepository u,InventoryRepository i){products=p;cats=c;sellers=s;users=u;inventory=i;}
@GetMapping("/products") Page<Map<String,Object>> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String q){Pageable pg=PageRequest.of(Math.min(page,100),Math.min(size,100),Sort.by("createdAt").descending());Page<Product> x=q==null?products.findByStatus(Product.Status.ACTIVE,pg):products.findByNameContainingIgnoreCaseAndStatus(q,Product.Status.ACTIVE,pg);return x.map(this::view);}
@GetMapping("/products/{id}") Map<String,Object> get(@PathVariable UUID id){return view(products.findById(id).orElseThrow(()->new ApiException("Product not found")));}
@PostMapping("/seller/products") Map<String,Object> create(@RequestBody @jakarta.validation.Valid ProductRequest r,Authentication a){User u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();SellerProfile s=sellers.findByUserId(u.getId()).orElseThrow(()->new ApiException("Seller profile required"));Category c=cats.findById(r.categoryId()).orElseThrow(()->new ApiException("Category not found"));if(s.getStatus()!=SellerProfile.Status.APPROVED) throw new ApiException("Seller profile is not approved"); Product p=new Product();p.setSeller(s);p.setCategory(c);p.setName(r.name());p.setDescription(r.description());p.setPrice(r.price());p.setStatus(Product.Status.DRAFT); p=products.save(p); Inventory inv=new Inventory(); inv.setProduct(p); inv.setAvailableQuantity(0); inv.setReservedQuantity(0); inventory.save(inv); return view(p);}
@GetMapping("/seller/products") List<Map<String,Object>> mine(Authentication a){User u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();SellerProfile s=sellers.findByUserId(u.getId()).orElseThrow(()->new ApiException("Seller profile required"));List<Product> list=products.findBySellerIdOrderByCreatedAtDesc(s.getId());List<Map<String,Object>> out=new ArrayList<>();for(Product p:list){Map<String,Object> v=new LinkedHashMap<>(view(p));int qty=inventory.findByProductId(p.getId()).map(Inventory::getAvailableQuantity).orElse(0);v.put("availableQuantity",qty);out.add(v);}return out;}
@PutMapping("/seller/products/{id}/stock") Map<String,Object> stock(@PathVariable UUID id,@RequestBody @jakarta.validation.Valid StockRequest r,Authentication a){Product p=products.findById(id).orElseThrow(()->new ApiException("Product not found")); checkOwner(p,a); Inventory i=inventory.findByProductId(id).orElseThrow(()->new ApiException("Inventory not found")); i.setAvailableQuantity(r.quantity()); inventory.save(i); return Map.of("productId",id,"availableQuantity",r.quantity());}
@PostMapping("/seller/products/{id}/activate") Map<String,Object> activate(@PathVariable UUID id,Authentication a){Product p=products.findById(id).orElseThrow(()->new ApiException("Product not found")); checkOwner(p,a); Inventory i=inventory.findByProductId(id).orElseThrow(()->new ApiException("Inventory not found")); if(i.getAvailableQuantity()<=0) throw new ApiException("Add inventory before activation"); p.setStatus(Product.Status.ACTIVE); products.save(p); return view(p);}
private void checkOwner(Product p,Authentication a){User u=users.findByEmailIgnoreCase(a.getName()).orElseThrow(); if(!p.getSeller().getUser().getId().equals(u.getId())) throw new ApiException("You do not own this product");}
private Map<String,Object> view(Product p){return Map.of("id",p.getId(),"name",p.getName(),"description",p.getDescription()==null?"":p.getDescription(),"price",p.getPrice(),"status",p.getStatus().name(),"category",p.getCategory().getName());}}
